primaryQuery:
run: order_items -> {
  aggregate:
    open_orders is count(order_id) { where: status = 'Processing' or status = 'Shipped' }
    open_line_items is count() { where: status = 'Processing' or status = 'Shipped' }
    undelivered_including_cancelled is count(order_id) { where: delivered_at is null }
}

verifyQuery:
run: order_items -> {
  group_by: order_id
  aggregate:
    open_items is count() { where: status = 'Processing' or status = 'Shipped' }
    undelivered_items is count() { where: delivered_at is null }
} -> {
  aggregate:
    open_orders is count() { where: open_items > 0 }
    open_line_items is open_items.sum()
    undelivered_including_cancelled is count() { where: undelivered_items > 0 }
}
